INSERT INTO collection_pages VALUES('b5803cc35d4133872b2869a182f096afc5f96bb8f6b862daf157b09e05089754','3f06ab12755a4c657a36f41eb78dd6e318dd59ed080b9b85e2cf823521ece472','{"hasNext":false,"items":[{"author":{"account":null,"email":"scholarmatch-bot@users.noreply.github.com","name":"scholarmatch-bot"},"authoredDate":"2026-06-24T21:12:06Z","committedDate":"2026-06-24T21:12:06Z","committer":{"account":null,"email":"scholarmatch-bot@users.noreply.github.com","name":"scholarmatch-bot"},"observedAt":"2026-10-08T23:30:27.371Z","repositoryId":1279609417,"sha":"085c3f70fc4965af076fac7b1ae05e991483fa2a"},{"author":{"account":null,"email":"z@container","name":"Z User"},"authoredDate":"2026-06-24T10:57:07Z","committedDate":"2026-06-24T15:40:21Z","committer":{"account":null,"email":"z@container","name":"Z User"},"observedAt":"2026-10-08T23:30:27.371Z","repositoryId":1279609417,"sha":"541f91e5227f2f42f22bc72435396e7c3abb399b"}],"observedAt":"2026-10-08T23:30:27.371Z","raw":[{"author":null,"comments_url":"https://api.github.com/repos/leemcchesneyclarkgmailcom/scholarmatch-ai/commits/085c3f70fc4965af076fac7b1ae05e991483fa2a/comments","commit":{"author":{"date":"2026-06-24T21:12:06Z","email":"scholarmatch-bot@users.noreply.github.com","name":"scholarmatch-bot"},"comment_count":0,"committer":{"date":"2026-06-24T21:12:06Z","email":"scholarmatch-bot@users.noreply.github.com","name":"scholarmatch-bot"},"message":"feat: ScholarMatch AI — full platform\n\nAI-powered scholarship discovery and recommendation platform.\n\nStudent Portal:\n- NextAuth credentials auth + signup with referral tracking\n- Academic/interests/career-goals profile builder with completion tracking\n- Dashboard with top matches, saved scholarships, deadlines, improvements\n- Saved scholarships with status tracking (Saved/Applied/Won/Lost) + notes\n\nAI Matching Engine:\n- Six-dimension weighted scoring (GPA, tests, education, major/interests, region, demographics)\n- Per-scholarship winning probability tuned by competitiveness\n- LLM-generated match narratives (z-ai-web-dev-sdk), cached per match\n- Actionable improvement suggestions\n\nScholarship Database:\n- 20 seeded scholarships across STEM, arts, need-based, heritage, international\n- AI discovery endpoint (LLM normalizes intent into structured records)\n- Slug-based duplicate detection\n- Deadline tracking with urgency badges + automatic expiry\n- Region/field/level/amount filtering\n\nAutomation:\n- Background worker (scripts/worker.js): hourly expiry + reminders, daily discovery\n- Deadline reminders for saved scholarships nearing close\n\nAdmin Dashboard:\n- KPI monitoring (users, scholarships, award value, matches, newsletter)\n- User growth + competitiveness charts (Recharts)\n- Scholarship moderation (inline status, delete with confirm)\n- On-demand AI discovery trigger\n\nGrowth:\n- Referral system with codes, email invites, milestone rewards\n- Newsletter with frequency preferences (daily/weekly/monthly)\n- Programmatic SEO hub pages by field/heritage/level/need\n- Expert application guides hub\n\nDesign:\n- Emerald + gold palette, mobile-first, accessible, dark mode\n- Sticky footer, custom ScoreRing + ScholarshipCard components\n- Zustand SPA nav store with URL sync\n\nDevOps:\n- Multi-stage production Dockerfile + docker-compose (app + worker)\n- GitHub Actions CI (lint, typecheck, build, docker smoke)\n- Branch protection recommendations\n- Background worker script for automated discovery + reminders\n- Comprehensive README + .env.example\n\nDemo accounts: admin@scholarmatch.ai/admin123, demo@scholarmatch.ai/student123","tree":{"sha":"dad0ec57a0e9c13f465e8235f84663097b2c0006","url":"https://api.github.com/repos/leemcchesneyclarkgmailcom/scholarmatch-ai/git/trees/dad0ec57a0e9c13f465e8235f84663097b2c0006"},"url":"https://api.github.com/repos/leemcchesneyclarkgmailcom/scholarmatch-ai/git/commits/085c3f70fc4965af076fac7b1ae05e991483fa2a","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":null,"html_url":"https://github.com/leemcchesneyclarkgmailcom/scholarmatch-ai/commit/085c3f70fc4965af076fac7b1ae05e991483fa2a","node_id":"C_kwDOTEVKSdoAKDA4NWMzZjcwZmM0OTY1YWYwNzZmYWM3YjFhZTA1ZTk5MTQ4M2ZhMmE","parents":[{"html_url":"https://github.com/leemcchesneyclarkgmailcom/scholarmatch-ai/commit/541f91e5227f2f42f22bc72435396e7c3abb399b","sha":"541f91e5227f2f42f22bc72435396e7c3abb399b","url":"https://api.github.com/repos/leemcchesneyclarkgmailcom/scholarmatch-ai/commits/541f91e5227f2f42f22bc72435396e7c3abb399b"}],"sha":"085c3f70fc4965af076fac7b1ae05e991483fa2a","url":"https://api.github.com/repos/leemcchesneyclarkgmailcom/scholarmatch-ai/commits/085c3f70fc4965af076fac7b1ae05e991483fa2a"},{"author":null,"comments_url":"https://api.github.com/repos/leemcchesneyclarkgmailcom/scholarmatch-ai/commits/541f91e5227f2f42f22bc72435396e7c3abb399b/comments","commit":{"author":{"date":"2026-06-24T10:57:07Z","email":"z@container","name":"Z User"},"comment_count":0,"committer":{"date":"2026-06-24T15:40:21Z","email":"z@container","name":"Z User"},"message":"Initial commit","tree":{"sha":"925a1af522b6004e2cee3c0d0bb9e7f3188817dc","url":"https://api.github.com/repos/leemcchesneyclarkgmailcom/scholarmatch-ai/git/trees/925a1af522b6004e2cee3c0d0bb9e7f3188817dc"},"url":"https://api.github.com/repos/leemcchesneyclarkgmailcom/scholarmatch-ai/git/commits/541f91e5227f2f42f22bc72435396e7c3abb399b","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":null,"html_url":"https://github.com/leemcchesneyclarkgmailcom/scholarmatch-ai/commit/541f91e5227f2f42f22bc72435396e7c3abb399b","node_id":"C_kwDOTEVKSdoAKDU0MWY5MWU1MjI3ZjJmNDJmMjJiYzcyNDM1Mzk2ZTdjM2FiYjM5OWI","parents":[],"sha":"541f91e5227f2f42f22bc72435396e7c3abb399b","url":"https://api.github.com/repos/leemcchesneyclarkgmailcom/scholarmatch-ai/commits/541f91e5227f2f42f22bc72435396e7c3abb399b"}],"requestUrl":"https://api.github.com/repos/